# ==============================================================================# 084_PROVIDER_REGISTRY_ENGINE.py## IOTEC PROVIDER REGISTRY ENGINE## Missão:# Registrar e selecionar provedores de capacidades.## Não executa consultas.# Não integra APIs.# Apenas mantém o catálogo oficial de provedores.# ==============================================================================from __future__ import annotationsimport sqlite3import hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class ProviderRegistryEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS provider_registry(            id INTEGER PRIMARY KEY AUTOINCREMENT,            timestamp TEXT,            provider_id TEXT,            provider_name TEXT,            capability TEXT,            provider_type TEXT,            version TEXT,            authentication TEXT,            priority INTEGER,            health_status TEXT,            enabled INTEGER,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def _hash(self, payload):        raw = json.dumps(            payload,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def register_provider(        self,        provider_name,        capability,        provider_type,        version,        authentication,        priority,        metadata=None    ):        metadata = metadata or {}        timestamp = datetime.utcnow().isoformat()        provider_id = hashlib.md5(            f"{timestamp}{provider_name}".encode()        ).hexdigest()        payload = {            "timestamp": timestamp,            "provider_id": provider_id,            "provider_name": provider_name,            "capability": capability,            "provider_type": provider_type,            "version": version,            "authentication": authentication,            "priority": priority,            "health_status": "UNKNOWN",            "enabled": 1,            "metadata": metadata        }        signature = self._hash(payload)        self.conn.execute("""        INSERT INTO provider_registry(            timestamp,            provider_id,            provider_name,            capability,            provider_type,            version,            authentication,            priority,            health_status,            enabled,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?)        """,(            payload["timestamp"],            payload["provider_id"],            payload["provider_name"],            payload["capability"],            payload["provider_type"],            payload["version"],            payload["authentication"],            payload["priority"],            payload["health_status"],            payload["enabled"],            json.dumps(payload["metadata"], ensure_ascii=False),            signature        ))        self.conn.commit()        payload["hash"] = signature        return payload    # ------------------------------------------------------------------    def get_best_provider(self, capability):        cur = self.conn.execute("""        SELECT *        FROM provider_registry        WHERE capability = ?          AND enabled = 1        ORDER BY priority DESC        LIMIT 1        """,(capability,))        row = cur.fetchone()        if row:            return dict(row)        return None# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    engine = ProviderRegistryEngine()    provider = engine.register_provider(        provider_name="EMPRESARIAL_PROVIDER_001",        capability="BASE_EMPRESARIAL",        provider_type="API",        version="1.0",        authentication="TOKEN",        priority=100,        metadata={            "status":"HOMOLOGADO",            "origin":"082_CAPABILITY_ADAPTER_MANAGER"        }    )    print("="*80)    print("PROVIDER REGISTRY")    print("="*80)    for k,v in provider.items():        print(f"{k:22}: {v}")    print("="*80)    print()    print("="*80)    print("BEST PROVIDER")    print("="*80)    best = engine.get_best_provider("BASE_EMPRESARIAL")    print(best)